def _filter_person_properties_for_flag(flag: FeatureFlag, person_properties: dict[str, Any]) -> dict[str, Any]:
    """
    Filter person_properties to only include keys referenced by the flag's conditions.

    Pass the flag whose conditions actually drove evaluation. For historical
    (timestamp-based) evaluations that means the *reconstructed* flag, not the live
    record: otherwise the response can leak property values that weren't relevant
    at the requested point in time.

    NOTE: cohort-typed conditions reference person properties indirectly via the
    cohort definition. This helper does not resolve that, so flags whose only
    conditions are cohorts will return an empty person_properties block.
    """
    referenced_keys: set[str] = set()
    for section in ("groups", "super_groups"):
        for group in flag.filters.get(section, []) or []:
            for prop in group.get("properties", []) or []:
                if prop.get("type") == "person" and prop.get("key"):
                    referenced_keys.add(prop["key"])
    for override in (flag.filters.get("multivariate", {}) or {}).get("override_property_values", []) or []:
        if override.get("type") == "person" and override.get("key"):
            referenced_keys.add(override["key"])
    return {k: v for k, v in person_properties.items() if k in referenced_keys}

